import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"逢纷","description":"","frontmatter":{"title":"逢纷","date":"2026-11-24T00:00:00.000Z","seq":48,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"刘向","source_book":"楚辞","prev":{"text":"株昭","link":"/blogs/楚辞/株昭.html"},"next":{"text":"离世","link":"/blogs/楚辞/离世.html"}},"headers":[],"relativePath":"blogs/楚辞/逢纷.md","filePath":"blogs/楚辞/逢纷.md"}'),o={name:"blogs/楚辞/逢纷.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="逢纷" tabindex="-1">逢纷 <a class="header-anchor" href="#逢纷" aria-label="Permalink to &quot;逢纷&quot;">​</a></h1><p class="poem-meta">先秦 · 刘向　·　九叹</p><div class="poem"><p class="poem-stanza">伊伯庸之末胄兮，谅皇直之屈原。</p><p class="poem-stanza">云余肇祖于高阳兮，惟楚怀之婵连。</p><p class="poem-stanza">原生受命于贞节兮，鸿永路有嘉名。</p><p class="poem-stanza">齐名字于天地兮，并光明于列星。</p><p class="poem-stanza">吸精粹而吐氛浊兮，横邪世而不取容。</p><p class="poem-stanza">行叩诚而不阿兮，遂见排而逢谗。</p><p class="poem-stanza">后听虚而黜实兮，不吾理而顺情。</p><p class="poem-stanza">肠愤悁而含怒兮，志迁蹇而左倾。</p><p class="poem-stanza">心戃慌其不我与兮，躬速速其不吾亲。</p><p class="poem-stanza">辞灵修而陨志兮，吟泽畔之江滨。</p><p class="poem-stanza">椒桂罗以颠覆兮，有竭信而归诚。</p><p class="poem-stanza">谗夫蔼蔼而漫著兮，曷其不舒予情？</p><p class="poem-stanza">始结言于庙堂兮，信中涂而叛之。</p><p class="poem-stanza">怀兰蕙与衡芷兮，行中野而散之。</p><p class="poem-stanza">声哀哀而怀高丘兮，心愁愁而思旧邦。</p><p class="poem-stanza">愿承闲而自恃兮，径淫曀而道壅。</p><p class="poem-stanza">颜霉黧以沮败兮，精越裂而衰耄。</p><p class="poem-stanza">裳襜襜而含风兮，衣纳纳而掩露。</p><p class="poem-stanza">赴江湘之湍流兮，顺波凑而下降。</p><p class="poem-stanza">徐徘徊于山阿兮，飘风来之洶洶。</p><p class="poem-stanza">驰余车兮玄石，步余马兮洞庭。</p><p class="poem-stanza">平明发兮苍梧，夕投宿兮石城。</p><p class="poem-stanza">芙蓉盖而菱华车兮，紫贝阙而玉堂。</p><p class="poem-stanza">薜荔饰而陆离荐兮，鱼鳞衣而白蜺裳。</p><p class="poem-stanza">登逢龙而下陨兮，违故都之漫漫。</p><p class="poem-stanza">思南郢之旧俗兮，肠一夕而九运。</p><p class="poem-stanza">扬流波之潢潢兮，体溶溶而东回。</p><p class="poem-stanza">心怊怅以永思兮，意晻晻而日颓。</p><p class="poem-stanza">白露纷以涂涂兮，秋风浏以萧萧。</p><p class="poem-stanza">身永流而不还兮，魂长逝而常愁。</p><p class="poem-stanza">叹曰：</p><p class="poem-stanza">譬彼流水纷扬磕兮，波逢汹涌濆壅滂兮。</p><p class="poem-stanza">揄扬涤荡飘流陨往触崟石兮，龙卬脟圈缭戾宛转阻相薄兮，</p><p class="poem-stanza">遭纷逢凶蹇离尤兮，垂文扬采遗将来兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
